511	    pub(crate) fn page_after(
512	        &self,
513	        session_id: &str,
514	        raw_cursor: &str,
515	        lease_id: &str,
516	    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
517	        if self.is_faulted(session_id) {
518	            return Err(ProjectionReset::Faulted);
519	        }
520	        let cursor = ProjectionCursor::parse(raw_cursor)?;
521	        if cursor.epoch.as_str() != self.epoch.as_ref() {
522	            return Err(ProjectionReset::WrongEpoch);
