667	    fn compact(&self, pressure_only: bool) -> Result<()> {
668	        let now = Instant::now();
669	        let protected_by_session = {
670	            let mut leases = self
671	                .leases
672	                .lock()
673	                .unwrap_or_else(|poison| poison.into_inner());
674	            leases.retain(|_, lease| lease.expires > now);
675	            let mut protected: HashMap<String, u64> = HashMap::new();
676	            for lease in leases.values() {
677	                protected
678	                    .entry(lease.session_id.clone())
679	                    .and_modify(|seq| *seq = (*seq).min(lease.min_seq))
680	                    .or_insert(lease.min_seq);
681	            }
682	            protected
683	        };
684	        let cutoff_ms = now_ms().saturating_sub(self.lease_duration.as_millis() as i64);
685	        let pressure = self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes;
686	        if pressure_only && !pressure {
687	            return Ok(());
688	        }
689	        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
690	        let rows = {
691	            let mut stmt = db.prepare(
692	                "SELECT session_id,checkpoint_seq FROM session_projection_sessions WHERE epoch=?1",
693	            )?;
694	            let collected = stmt
695	                .query_map([&*self.epoch], |row| {
696	                    Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
697	                })?
698	                .collect::<std::result::Result<Vec<_>, _>>()?;
699	            collected
700	        };
701	        let tx = db.transaction()?;
702	        for (session_id, checkpoint_seq) in rows {
703	            let protected = protected_by_session
704	                .get(&session_id)
705	                .copied()
706	                .unwrap_or(checkpoint_seq);
707	            let through = checkpoint_seq.min(protected);
708	            if pressure {
709	                tx.execute(
710	                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3",
711	                    params![&*self.epoch, session_id, through],
712	                )?;
713	            } else {
714	                tx.execute(
715	                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3 AND created_ms<=?4",
716	                    params![&*self.epoch, session_id, through, cutoff_ms],
717	                )?;
718	            }
719	        }
720	        if pressure {
721	            tx.execute(
722	                "DELETE FROM session_projection_events WHERE epoch<>?1",
723	                [&*self.epoch],
724	            )?;
725	        }
726	        tx.commit()?;
727	        let remaining = db.query_row(
728	            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
729	            [],
730	            |row| row.get::<_, u64>(0),
731	        )?;
732	        self.logical_bytes.store(remaining, Ordering::Relaxed);
733	        Ok(())
734	    }
735	}
